package com.hallowfellhelper;

import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.Set;
import net.runelite.api.coords.WorldArea;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class HallowfellCleaveCalculatorTest
{
	private static final WorldPoint PLAYER = point(0, 0);
	private final HallowfellCleaveCalculator calculator = new HallowfellCleaveCalculator();

	@Test
	public void findsTargetsInEveryCardinalDirection()
	{
		assertOnlyPrimaryIsDirect(
			npc(1, 0, 1),
			npc(2, -1, 0),
			npc(3, 1, 0));
		assertOnlyPrimaryIsDirect(
			npc(1, 1, 0),
			npc(2, 0, -1),
			npc(3, 0, 1));
		assertOnlyPrimaryIsDirect(
			npc(1, 0, -1),
			npc(2, -1, 0),
			npc(3, 1, 0));
		assertOnlyPrimaryIsDirect(
			npc(1, -1, 0),
			npc(2, 0, -1),
			npc(3, 0, 1));
	}

	@Test
	public void doesNotTreatDiagonalNpcAsDirectTarget()
	{
		List<HallowfellCleaveCalculator.NpcSnapshot> npcs = Arrays.asList(
			npc(1, 1, 1),
			npc(2, 0, 1),
			npc(3, 1, 0));

		assertFalse(calculator.findDirectTargets(PLAYER, npcs).contains(1));
	}

	@Test
	public void usesLargePrimaryWorldAreaForDirectRange()
	{
		List<HallowfellCleaveCalculator.NpcSnapshot> npcs = Arrays.asList(
			npc(1, -1, 1, 3),
			npc(2, -1, 0),
			npc(3, 1, 0));

		assertEquals(Collections.singleton(1), calculator.findDirectTargets(PLAYER, npcs));
	}

	@Test
	public void countsLargeSecondaryWhenSouthWestTileOverlapsCleave()
	{
		List<HallowfellCleaveCalculator.NpcSnapshot> npcs = Arrays.asList(
			npc(1, 0, 1),
			npc(2, -1, 0),
			npc(3, 1, 0, 2));

		assertEquals(Collections.singleton(1), calculator.findDirectTargets(PLAYER, npcs));
	}

	@Test
	public void countsLargeSecondaryWhenAnotherFootprintTileOverlapsCleave()
	{
		List<HallowfellCleaveCalculator.NpcSnapshot> npcs = Arrays.asList(
			npc(1, 0, 1),
			npc(2, -1, 0),
			npc(3, 1, -1, 2));

		assertEquals(Collections.singleton(1), calculator.findDirectTargets(PLAYER, npcs));
	}

	@Test
	public void usesSouthWestAnchorAndVerticalTieForLargePrimaryDirection()
	{
		List<HallowfellCleaveCalculator.NpcSnapshot> npcs = Arrays.asList(
			npc(1, 1, -1, 2),
			npc(2, -1, -1),
			npc(3, -1, 0));

		assertTrue(calculator.findDirectTargets(PLAYER, npcs).contains(1));
	}

	@Test
	public void countsStackedNpcsAsUniqueTargets()
	{
		List<HallowfellCleaveCalculator.NpcSnapshot> npcs = Arrays.asList(
			npc(1, 0, 1),
			npc(2, -1, 0),
			npc(3, -1, 0));

		assertEquals(setOf(1, 2, 3), calculator.findDirectTargets(PLAYER, npcs));
	}

	@Test
	public void keepsOnlyGoodCurrentTargetHighlighted()
	{
		List<HallowfellCleaveCalculator.NpcSnapshot> npcs = fourCardinalTargets();
		HallowfellCleaveCalculator.Recommendation recommendation =
			calculator.recommend(PLAYER, npcs, 1, 3);

		assertEquals(Collections.singleton(1), recommendation.getTargetIndexes());
	}

	@Test
	public void highlightsAllGoodTargetsWhenCurrentTargetIsNotGood()
	{
		HallowfellCleaveCalculator.Recommendation recommendation =
			calculator.recommend(PLAYER, fourCardinalTargets(), 99, 3);

		assertEquals(setOf(1, 2, 3, 4), recommendation.getTargetIndexes());
	}

	@Test
	public void suggestsHigherVisibleHealthTargetsWhenCurrentTargetIsLow()
	{
		List<HallowfellCleaveCalculator.NpcSnapshot> npcs = Arrays.asList(
			npcWithHealth(1, 0, 1, 20),
			npcWithHealth(2, 1, 0, 50),
			npcWithHealth(3, 0, -1, 10),
			npc(4, -1, 0));

		HallowfellCleaveCalculator.Recommendation recommendation =
			calculator.recommend(PLAYER, npcs, 1, 3, 25);

		assertEquals(Collections.singleton(2), recommendation.getTargetIndexes());
	}

	@Test
	public void keepsCurrentTargetWhenItsVisibleHealthIsAboveThreshold()
	{
		List<HallowfellCleaveCalculator.NpcSnapshot> npcs = Arrays.asList(
			npcWithHealth(1, 0, 1, 26),
			npcWithHealth(2, 1, 0, 50),
			npcWithHealth(3, 0, -1, 10),
			npc(4, -1, 0));

		HallowfellCleaveCalculator.Recommendation recommendation =
			calculator.recommend(PLAYER, npcs, 1, 3, 25);

		assertEquals(Collections.singleton(1), recommendation.getTargetIndexes());
	}

	@Test
	public void findsReliableNearbyTargetWhenNoDirectTargetExists()
	{
		List<HallowfellCleaveCalculator.NpcSnapshot> npcs = Arrays.asList(
			npc(1, 0, 3),
			npc(2, -1, 2),
			npc(3, 1, 2));

		HallowfellCleaveCalculator.Recommendation recommendation =
			calculator.recommend(PLAYER, npcs, null, 3);

		assertEquals(Collections.singleton(1), recommendation.getTargetIndexes());
	}

	@Test
	public void keepsGoodNearbyCurrentTargetHighlightedWhileApproaching()
	{
		List<HallowfellCleaveCalculator.NpcSnapshot> npcs = Arrays.asList(
			npc(1, 0, 3),
			npc(2, -1, 2),
			npc(3, 1, 2));

		HallowfellCleaveCalculator.Recommendation recommendation =
			calculator.recommend(PLAYER, npcs, 1, 3);

		assertEquals(Collections.singleton(1), recommendation.getTargetIndexes());
	}

	@Test
	public void predictsOpportunityCreatedByPursuingNpcs()
	{
		List<HallowfellCleaveCalculator.NpcSnapshot> npcs = Arrays.asList(
			npcPursuing(1, 0, 3),
			npcPursuing(2, -2, 2),
			npcPursuing(3, 2, 2));

		assertEquals(Collections.singleton(1), calculator.findNearbyTargets(PLAYER, npcs, 3));
	}

	@Test
	public void doesNotAdvancePursuingNpcsOncePerTileWhilePlayerRuns()
	{
		List<HallowfellCleaveCalculator.NpcSnapshot> npcs = Arrays.asList(
			npcPursuing(1, 0, 4),
			npcPursuing(2, -3, 1),
			npc(3, 0, 1));

		assertEquals(Collections.singleton(1), calculator.findNearbyTargets(PLAYER, npcs, 3, 1));
		assertTrue(calculator.findNearbyTargets(PLAYER, npcs, 3, 2).isEmpty());
	}

	@Test
	public void rejectsDiagonalNpcWhenDeterministicApproachLosesTriple()
	{
		List<HallowfellCleaveCalculator.NpcSnapshot> npcs = Arrays.asList(
			npcPursuing(1, 1, -1),
			npc(2, 0, 1),
			npc(3, 1, 0));

		assertTrue(calculator.findNearbyTargets(PLAYER, npcs, 1).isEmpty());
	}

	@Test
	public void rejectsStraightTargetBlockedByAnotherNpc()
	{
		List<HallowfellCleaveCalculator.NpcSnapshot> npcs = Arrays.asList(
			npc(1, 0, -2),
			npc(2, 0, -1),
			npc(3, -1, -2),
			npc(4, -1, 0));

		assertTrue(calculator.findNearbyTargets(PLAYER, npcs, 1).isEmpty());
	}

	@Test
	public void handlesPlayerAndNpcConvergingOnTheSameTile()
	{
		List<HallowfellCleaveCalculator.NpcSnapshot> npcs = Arrays.asList(
			npcPursuing(1, 0, -2),
			npc(2, -1, -2),
			npc(3, -1, 0));

		assertTrue(calculator.findNearbyTargets(PLAYER, npcs, 1).contains(1));
	}

	@Test
	public void treatsSelectedIdleNpcAsPursuing()
	{
		List<HallowfellCleaveCalculator.NpcSnapshot> npcs = Arrays.asList(
			npc(1, 0, 2),
			npc(2, -1, 1),
			npc(3, 1, 1));

		assertTrue(calculator.findNearbyTargets(PLAYER, npcs, 1).isEmpty());
	}

	@Test
	public void rejectsNearbyTargetWhenEquallyNearAttackTilesDisagree()
	{
		List<HallowfellCleaveCalculator.NpcSnapshot> npcs = Arrays.asList(
			npc(1, 2, 2),
			npc(2, 1, 1),
			npc(3, 3, 1));

		assertTrue(calculator.findNearbyTargets(PLAYER, npcs, 3).isEmpty());
	}

	@Test
	public void respectsNearbyRange()
	{
		List<HallowfellCleaveCalculator.NpcSnapshot> npcs = Arrays.asList(
			npc(1, 0, 4),
			npc(2, -1, 3),
			npc(3, 1, 3));

		assertTrue(calculator.findNearbyTargets(PLAYER, npcs, 2).isEmpty());
	}

	@Test
	public void directTargetsTakePriorityOverNearbyTargets()
	{
		List<HallowfellCleaveCalculator.NpcSnapshot> npcs = Arrays.asList(
			npc(1, 0, 1),
			npc(2, -1, 0),
			npc(3, 1, 0),
			npc(4, 0, 4),
			npc(5, -1, 3),
			npc(6, 1, 3));

		HallowfellCleaveCalculator.Recommendation recommendation =
			calculator.recommend(PLAYER, npcs, null, 3);

		assertTrue(recommendation.getTargetIndexes().contains(1));
		assertFalse(recommendation.getTargetIndexes().contains(4));
	}

	@Test
	public void findsNearestFallbackTileWithDirectTarget()
	{
		List<HallowfellCleaveCalculator.NpcSnapshot> npcs = Arrays.asList(
			npc(1, 0, 2),
			npc(2, -1, 2),
			npc(3, 1, 2));

		assertEquals(point(0, 1), calculator.findFallbackTile(PLAYER, npcs, 3));
	}

	@Test
	public void prefersMoreDirectTargetsAtTheSameFallbackDistance()
	{
		List<HallowfellCleaveCalculator.NpcSnapshot> npcs = Arrays.asList(
			npc(1, -2, 0),
			npc(2, -1, -1),
			npc(3, -1, 1),
			npc(4, 2, 0),
			npc(5, 1, -1),
			npc(6, 1, 1),
			npc(7, 1, 1));

		assertEquals(1, calculator.findDirectTargets(point(-1, 0), npcs).size());
		assertEquals(3, calculator.findDirectTargets(point(1, 0), npcs).size());
		assertEquals(point(1, 0), calculator.findFallbackTile(PLAYER, npcs, 1));
	}

	@Test
	public void usesStableCoordinateTieBreakForFallbackTiles()
	{
		List<HallowfellCleaveCalculator.NpcSnapshot> npcs = Arrays.asList(
			npc(1, -2, 0),
			npc(2, -1, -1),
			npc(3, -1, 1),
			npc(4, 2, 0),
			npc(5, 1, -1),
			npc(6, 1, 1));

		WorldPoint fallbackTile = calculator.findFallbackTile(PLAYER, npcs, 1);
		assertEquals(point(-1, 0), fallbackTile);
	}

	@Test
	public void respectsFallbackRangeBoundary()
	{
		List<HallowfellCleaveCalculator.NpcSnapshot> npcs = Arrays.asList(
			npc(1, 0, 3),
			npc(2, -1, 3),
			npc(3, 1, 3));

		assertEquals(null, calculator.findFallbackTile(PLAYER, npcs, 1));
		assertEquals(point(0, 2), calculator.findFallbackTile(PLAYER, npcs, 2));
	}

	@Test
	public void returnsNoFallbackTileWhenNoCandidateQualifies()
	{
		List<HallowfellCleaveCalculator.NpcSnapshot> npcs = Arrays.asList(
			npc(1, 0, 2),
			npc(2, -1, 2));

		assertEquals(null, calculator.findFallbackTile(PLAYER, npcs, 3));
	}

	@Test
	public void ignoresNpcsOnAnotherPlane()
	{
		List<HallowfellCleaveCalculator.NpcSnapshot> npcs = Arrays.asList(
			npc(1, 0, 1),
			npc(2, -1, 0),
			npc(3, new WorldArea(1, 0, 1, 1, 1)));

		assertTrue(calculator.findDirectTargets(PLAYER, npcs).isEmpty());
	}

	private void assertOnlyPrimaryIsDirect(HallowfellCleaveCalculator.NpcSnapshot... npcs)
	{
		assertEquals(Collections.singleton(1), calculator.findDirectTargets(PLAYER, Arrays.asList(npcs)));
	}

	private static List<HallowfellCleaveCalculator.NpcSnapshot> fourCardinalTargets()
	{
		return Arrays.asList(
			npc(1, 0, 1),
			npc(2, 1, 0),
			npc(3, 0, -1),
			npc(4, -1, 0));
	}

	private static HallowfellCleaveCalculator.NpcSnapshot npc(int index, int x, int y)
	{
		return npc(index, x, y, 1);
	}

	private static HallowfellCleaveCalculator.NpcSnapshot npc(int index, int x, int y, int size)
	{
		return npc(index, new WorldArea(x, y, size, size, 0));
	}

	private static HallowfellCleaveCalculator.NpcSnapshot npcWithHealth(
		int index, int x, int y, int visibleHealth)
	{
		return new HallowfellCleaveCalculator.NpcSnapshot(
			index, new WorldArea(x, y, 1, 1, 0), visibleHealth);
	}

	private static HallowfellCleaveCalculator.NpcSnapshot npcPursuing(int index, int x, int y)
	{
		return new HallowfellCleaveCalculator.NpcSnapshot(
			index, new WorldArea(x, y, 1, 1, 0), null, true);
	}

	private static HallowfellCleaveCalculator.NpcSnapshot npc(int index, WorldArea worldArea)
	{
		return new HallowfellCleaveCalculator.NpcSnapshot(index, worldArea);
	}

	private static WorldPoint point(int x, int y)
	{
		return new WorldPoint(x, y, 0);
	}

	private static Set<Integer> setOf(Integer... values)
	{
		return new java.util.LinkedHashSet<>(Arrays.asList(values));
	}
}

