package com.hallowfellhelper;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.annotation.Nullable;
import net.runelite.api.WorldView;
import net.runelite.api.coords.WorldArea;
import net.runelite.api.coords.WorldPoint;

final class HallowfellCleaveCalculator
{
	private static final int REQUIRED_SECONDARY_TARGETS = 2;

	Recommendation recommend(
		WorldPoint playerLocation,
		List<NpcSnapshot> npcs,
		@Nullable Integer currentTargetIndex,
		int nearbyRange)
	{
		return recommend(playerLocation, npcs, currentTargetIndex, nearbyRange, 0);
	}

	Recommendation recommend(
		WorldPoint playerLocation,
		List<NpcSnapshot> npcs,
		@Nullable Integer currentTargetIndex,
		int nearbyRange,
		int switchBelowHp)
	{
		return recommend(playerLocation, npcs, currentTargetIndex, nearbyRange, switchBelowHp, null, 1);
	}

	Recommendation recommend(
		WorldPoint playerLocation,
		List<NpcSnapshot> npcs,
		@Nullable Integer currentTargetIndex,
		int nearbyRange,
		int switchBelowHp,
		@Nullable WorldView worldView)
	{
		return recommend(
			playerLocation, npcs, currentTargetIndex, nearbyRange, switchBelowHp, worldView, 1);
	}

	Recommendation recommend(
		WorldPoint playerLocation,
		List<NpcSnapshot> npcs,
		@Nullable Integer currentTargetIndex,
		int nearbyRange,
		int switchBelowHp,
		@Nullable WorldView worldView,
		int playerStepsPerTick)
	{
		Set<Integer> directTargets = findDirectTargets(playerLocation, npcs);
		if (currentTargetIndex != null && directTargets.contains(currentTargetIndex))
		{
			Set<Integer> switchTargets = findHigherHealthTargets(
				directTargets, npcs, currentTargetIndex, switchBelowHp);
			if (!switchTargets.isEmpty())
			{
				return Recommendation.targets(switchTargets);
			}
			return Recommendation.currentTarget(currentTargetIndex);
		}

		if (!directTargets.isEmpty())
		{
			return Recommendation.targets(directTargets);
		}

		Set<Integer> nearbyTargets = findNearbyTargets(
			playerLocation, npcs, nearbyRange, worldView, playerStepsPerTick);
		if (currentTargetIndex != null && nearbyTargets.contains(currentTargetIndex))
		{
			Set<Integer> switchTargets = findHigherHealthTargets(
				nearbyTargets, npcs, currentTargetIndex, switchBelowHp);
			if (!switchTargets.isEmpty())
			{
				return Recommendation.targets(switchTargets);
			}
			return Recommendation.currentTarget(currentTargetIndex);
		}

		return Recommendation.targets(nearbyTargets);
	}

	private static Set<Integer> findHigherHealthTargets(
		Set<Integer> goodTargets,
		List<NpcSnapshot> npcs,
		int currentTargetIndex,
		int switchBelowHp)
	{
		if (switchBelowHp <= 0)
		{
			return Collections.emptySet();
		}

		Integer currentHealth = null;
		for (NpcSnapshot npc : npcs)
		{
			if (npc.getIndex() == currentTargetIndex)
			{
				currentHealth = npc.getVisibleHealth();
				break;
			}
		}
		if (currentHealth == null || currentHealth > switchBelowHp)
		{
			return Collections.emptySet();
		}

		Set<Integer> switchTargets = new LinkedHashSet<>();
		for (NpcSnapshot npc : npcs)
		{
			Integer health = npc.getVisibleHealth();
			if (npc.getIndex() != currentTargetIndex
				&& goodTargets.contains(npc.getIndex())
				&& health != null
				&& health > currentHealth)
			{
				switchTargets.add(npc.getIndex());
			}
		}
		return switchTargets;
	}

	Set<Integer> findDirectTargets(WorldPoint playerLocation, List<NpcSnapshot> npcs)
	{
		Set<Integer> targets = new LinkedHashSet<>();
		for (NpcSnapshot primary : npcs)
		{
			if (isDirectlyAttackable(playerLocation, primary.getWorldArea())
				&& hasThreeHits(playerLocation, primary, npcs))
			{
				targets.add(primary.getIndex());
			}
		}
		return targets;
	}

	@Nullable
	WorldPoint findFallbackTile(
		WorldPoint playerLocation,
		List<NpcSnapshot> npcs,
		int nearbyRange)
	{
		return findFallbackTile(playerLocation, npcs, nearbyRange, null);
	}

	/**
	 * Finds a nearby stand tile that has at least one direct three-hit target.
	 * Static collision is used for reachability; NPC occupancy is intentionally ignored.
	 */
	@Nullable
	WorldPoint findFallbackTile(
		WorldPoint playerLocation,
		List<NpcSnapshot> npcs,
		int nearbyRange,
		@Nullable WorldView worldView)
	{
		int maxDistance = Math.max(0, nearbyRange);
		Map<WorldPoint, Integer> distances = new HashMap<>();
		List<WorldPoint> queue = new ArrayList<>();
		distances.put(playerLocation, 0);
		queue.add(playerLocation);

		for (int queueIndex = 0; queueIndex < queue.size(); queueIndex++)
		{
			WorldPoint location = queue.get(queueIndex);
			int distance = distances.get(location);
			if (distance >= maxDistance)
			{
				continue;
			}

			for (int deltaX = -1; deltaX <= 1; deltaX++)
			{
				for (int deltaY = -1; deltaY <= 1; deltaY++)
				{
					if (deltaX == 0 && deltaY == 0)
					{
						continue;
					}

					WorldPoint next = new WorldPoint(
						location.getX() + deltaX,
						location.getY() + deltaY,
						location.getPlane());
					if (worldView != null && !WorldPoint.isInScene(
						worldView, next.getX(), next.getY()))
					{
						continue;
					}
					if (!canTravel(location.toWorldArea(), deltaX, deltaY, worldView)
						|| distances.containsKey(next))
					{
						continue;
					}

					distances.put(next, distance + 1);
					queue.add(next);
				}
			}
		}

		WorldPoint bestTile = null;
		int bestDistance = Integer.MAX_VALUE;
		int bestTargetCount = 0;
		for (Map.Entry<WorldPoint, Integer> entry : distances.entrySet())
		{
			WorldPoint candidate = entry.getKey();
			int distance = entry.getValue();
			Set<Integer> directTargets = findDirectTargets(candidate, npcs);
			int targetCount = directTargets.size();
			if (targetCount == 0
				|| distance > bestDistance
				|| (distance == bestDistance && targetCount < bestTargetCount)
				|| (distance == bestDistance && targetCount == bestTargetCount
					&& compareWorldPoints(candidate, bestTile) >= 0))
			{
				continue;
			}

			bestTile = candidate;
			bestDistance = distance;
			bestTargetCount = targetCount;
		}
		return bestTile;
	}

	private static int compareWorldPoints(WorldPoint first, @Nullable WorldPoint second)
	{
		if (second == null)
		{
			return -1;
		}

		int xComparison = Integer.compare(first.getX(), second.getX());
		if (xComparison != 0)
		{
			return xComparison;
		}
		int yComparison = Integer.compare(first.getY(), second.getY());
		if (yComparison != 0)
		{
			return yComparison;
		}
		return Integer.compare(first.getPlane(), second.getPlane());
	}

	Set<Integer> findNearbyTargets(WorldPoint playerLocation, List<NpcSnapshot> npcs, int nearbyRange)
	{
		return findNearbyTargets(playerLocation, npcs, nearbyRange, 1);
	}

	Set<Integer> findNearbyTargets(
		WorldPoint playerLocation,
		List<NpcSnapshot> npcs,
		int nearbyRange,
		int playerStepsPerTick)
	{
		return findNearbyTargets(playerLocation, npcs, nearbyRange, null, playerStepsPerTick);
	}

	private Set<Integer> findNearbyTargets(
		WorldPoint playerLocation,
		List<NpcSnapshot> npcs,
		int nearbyRange,
		@Nullable WorldView worldView,
		int playerStepsPerTick)
	{
		int movementSpeed = Math.max(1, playerStepsPerTick);
		Set<Integer> targets = new LinkedHashSet<>();
		for (NpcSnapshot primary : npcs)
		{
			if (!isDirectlyAttackable(playerLocation, primary.getWorldArea())
				&& isReliableNearbyTarget(
					playerLocation, primary, npcs, nearbyRange, worldView, movementSpeed))
			{
				targets.add(primary.getIndex());
			}
		}
		return targets;
	}

	private boolean isReliableNearbyTarget(
		WorldPoint playerLocation,
		NpcSnapshot primary,
		List<NpcSnapshot> npcs,
		int nearbyRange,
		@Nullable WorldView worldView,
		int playerStepsPerTick)
	{
		List<MovementState> states = Collections.singletonList(new MovementState(playerLocation, npcs));
		boolean reachedAttackRange = false;

		for (int movement = 0; movement <= nearbyRange; movement++)
		{
			List<MovementState> nextStates = new ArrayList<>();
			for (MovementState state : states)
			{
				NpcSnapshot currentPrimary = findNpc(state.getNpcs(), primary.getIndex());
				if (currentPrimary == null)
				{
					return false;
				}

				if (isDirectlyAttackable(state.getPlayerLocation(), currentPrimary.getWorldArea()))
				{
					reachedAttackRange = true;
					if (!hasThreeHits(state.getPlayerLocation(), currentPrimary, state.getNpcs()))
					{
						return false;
					}
					continue;
				}

				if (movement == nearbyRange)
				{
					return false;
				}

				List<WorldPoint> plannedPlayerMoves = getBestPlayerMoves(
					state.getPlayerLocation(), currentPrimary.getWorldArea(), worldView);
				if (plannedPlayerMoves.isEmpty())
				{
					return false;
				}

				List<NpcSnapshot> projectedNpcs = movement % playerStepsPerTick == 0
					? projectPursuingNpcs(
						state.getNpcs(), state.getPlayerLocation(), primary.getIndex(), worldView)
					: state.getNpcs();
				NpcSnapshot projectedPrimary = findNpc(projectedNpcs, primary.getIndex());
				if (projectedPrimary == null)
				{
					return false;
				}

				for (WorldPoint plannedPlayerMove : plannedPlayerMoves)
				{
					List<WorldPoint> resolvedPlayerMoves = resolvePlayerNpcConvergence(
						state.getPlayerLocation(),
						plannedPlayerMove,
						projectedPrimary.getWorldArea(),
						worldView);
					if (resolvedPlayerMoves.isEmpty())
					{
						return false;
					}

					for (WorldPoint playerMove : resolvedPlayerMoves)
					{
						nextStates.add(new MovementState(
							playerMove,
							projectedNpcs));
					}
				}
			}

			states = nextStates;
			if (states.isEmpty())
			{
				break;
			}
		}

		return reachedAttackRange;
	}

	@Nullable
	private static NpcSnapshot findNpc(List<NpcSnapshot> npcs, int index)
	{
		for (NpcSnapshot npc : npcs)
		{
			if (npc.getIndex() == index)
			{
				return npc;
			}
		}
		return null;
	}

	private static List<WorldPoint> getBestPlayerMoves(
		WorldPoint playerLocation,
		WorldArea targetArea,
		@Nullable WorldView worldView)
	{
		int currentDistance = distanceToAttackTile(playerLocation, targetArea);
		int targetMaxX = targetArea.getX() + targetArea.getWidth() - 1;
		int targetMaxY = targetArea.getY() + targetArea.getHeight() - 1;
		int preferredDeltaX = playerLocation.getX() < targetArea.getX() ? 1
			: playerLocation.getX() > targetMaxX ? -1 : 0;
		int preferredDeltaY = playerLocation.getY() < targetArea.getY() ? 1
			: playerLocation.getY() > targetMaxY ? -1 : 0;
		WorldPoint preferredMove = new WorldPoint(
			playerLocation.getX() + preferredDeltaX,
			playerLocation.getY() + preferredDeltaY,
			playerLocation.getPlane());
		if (!targetArea.contains(preferredMove)
			&& canTravel(playerLocation.toWorldArea(), preferredDeltaX, preferredDeltaY, worldView)
			&& distanceToAttackTile(preferredMove, targetArea) < currentDistance)
		{
			return Collections.singletonList(preferredMove);
		}

		int bestDistance = Integer.MAX_VALUE;
		List<WorldPoint> moves = new ArrayList<>();
		for (int deltaX = -1; deltaX <= 1; deltaX++)
		{
			for (int deltaY = -1; deltaY <= 1; deltaY++)
			{
				if (deltaX == 0 && deltaY == 0)
				{
					continue;
				}

				WorldPoint move = new WorldPoint(
					playerLocation.getX() + deltaX,
					playerLocation.getY() + deltaY,
					playerLocation.getPlane());
				if (targetArea.contains(move))
				{
					continue;
				}
				if (!canTravel(playerLocation.toWorldArea(), deltaX, deltaY, worldView))
				{
					continue;
				}

				int distance = distanceToAttackTile(move, targetArea);
				if (distance >= currentDistance || distance > bestDistance)
				{
					continue;
				}
				if (distance < bestDistance)
				{
					moves.clear();
					bestDistance = distance;
				}
				moves.add(move);
			}
		}
		return moves;
	}

	private static List<WorldPoint> resolvePlayerNpcConvergence(
		WorldPoint playerLocation,
		WorldPoint plannedPlayerMove,
		WorldArea projectedTargetArea,
		@Nullable WorldView worldView)
	{
		if (!projectedTargetArea.contains(plannedPlayerMove))
		{
			return Collections.singletonList(plannedPlayerMove);
		}

		int deltaX = Integer.signum(plannedPlayerMove.getX() - playerLocation.getX());
		int deltaY = Integer.signum(plannedPlayerMove.getY() - playerLocation.getY());
		int[][] fallbackDirections;
		if (deltaX != 0 && deltaY == 0)
		{
			fallbackDirections = new int[][]{{deltaX, -1}, {deltaX, 1}};
		}
		else if (deltaY != 0 && deltaX == 0)
		{
			fallbackDirections = new int[][]{{-1, deltaY}, {1, deltaY}};
		}
		else
		{
			fallbackDirections = new int[][]{{deltaX, 0}, {0, deltaY}};
		}

		for (int[] direction : fallbackDirections)
		{
			WorldPoint alternative = new WorldPoint(
				playerLocation.getX() + direction[0],
				playerLocation.getY() + direction[1],
				playerLocation.getPlane());
			if (!projectedTargetArea.contains(alternative)
				&& isDirectlyAttackable(alternative, projectedTargetArea)
				&& canTravel(
					playerLocation.toWorldArea(), direction[0], direction[1], worldView))
			{
				return Collections.singletonList(alternative);
			}
		}
		return Collections.emptyList();
	}

	private static int distanceToAttackTile(WorldPoint playerLocation, WorldArea targetArea)
	{
		int distance = Integer.MAX_VALUE;
		for (WorldPoint attackTile : getAttackTiles(targetArea))
		{
			distance = Math.min(distance, playerLocation.distanceTo(attackTile));
		}
		return distance;
	}

	private static List<NpcSnapshot> projectPursuingNpcs(
		List<NpcSnapshot> npcs,
		WorldPoint playerLocation,
		int primaryIndex,
		@Nullable WorldView worldView)
	{
		List<NpcSnapshot> orderedNpcs = new ArrayList<>(npcs);
		orderedNpcs.sort((first, second) -> Integer.compare(first.getIndex(), second.getIndex()));
		List<NpcSnapshot> projected = new ArrayList<>(npcs.size());
		List<WorldArea> reservedDestinations = new ArrayList<>();
		for (NpcSnapshot npc : orderedNpcs)
		{
			boolean pursuingPlayer = npc.isPursuingPlayer() || npc.getIndex() == primaryIndex;
			WorldArea projectedArea = pursuingPlayer
				? getNpcMoveTowards(
					npc, playerLocation, npcs, reservedDestinations, worldView)
				: npc.getWorldArea();
			projected.add(npc.withWorldArea(projectedArea));
			reservedDestinations.add(projectedArea);
		}
		return projected;
	}

	private static WorldArea getNpcMoveTowards(
		NpcSnapshot npc,
		WorldPoint playerLocation,
		List<NpcSnapshot> npcs,
		List<WorldArea> reservedDestinations,
		@Nullable WorldView worldView)
	{
		WorldArea area = npc.getWorldArea();
		if (area.contains(playerLocation) || area.isInMeleeDistance(playerLocation))
		{
			return area;
		}

		int maxX = area.getX() + area.getWidth() - 1;
		int maxY = area.getY() + area.getHeight() - 1;
		int deltaX = playerLocation.getX() < area.getX() ? -1
			: playerLocation.getX() > maxX ? 1 : 0;
		int deltaY = playerLocation.getY() < area.getY() ? -1
			: playerLocation.getY() > maxY ? 1 : 0;
		WorldArea diagonalMove = translate(area, deltaX, deltaY);
		if (!diagonalMove.contains(playerLocation)
			&& canNpcTravel(
				npc, diagonalMove, deltaX, deltaY, npcs, reservedDestinations, worldView))
		{
			return diagonalMove;
		}

		WorldArea xMove = translate(area, deltaX, 0);
		if (deltaX != 0 && !xMove.contains(playerLocation)
			&& canNpcTravel(
				npc, xMove, deltaX, 0, npcs, reservedDestinations, worldView))
		{
			return xMove;
		}
		WorldArea yMove = translate(area, 0, deltaY);
		if (deltaY != 0 && !yMove.contains(playerLocation)
			&& canNpcTravel(
				npc, yMove, 0, deltaY, npcs, reservedDestinations, worldView))
		{
			return yMove;
		}
		return area;
	}

	private static boolean canNpcTravel(
		NpcSnapshot npc,
		WorldArea destination,
		int deltaX,
		int deltaY,
		List<NpcSnapshot> npcs,
		List<WorldArea> reservedDestinations,
		@Nullable WorldView worldView)
	{
		for (NpcSnapshot other : npcs)
		{
			if (other.getIndex() != npc.getIndex()
				&& destination.intersectsWith(other.getWorldArea()))
			{
				return false;
			}
		}
		for (WorldArea reservedDestination : reservedDestinations)
		{
			if (destination.intersectsWith(reservedDestination))
			{
				return false;
			}
		}
		return canTravel(npc.getWorldArea(), deltaX, deltaY, worldView);
	}

	private static boolean canTravel(
		WorldArea area,
		int deltaX,
		int deltaY,
		@Nullable WorldView worldView)
	{
		return worldView == null || (deltaX == 0 && deltaY == 0)
			|| area.canTravelInDirection(worldView, deltaX, deltaY);
	}

	private static WorldArea translate(WorldArea area, int deltaX, int deltaY)
	{
		return new WorldArea(
			area.getX() + deltaX,
			area.getY() + deltaY,
			area.getWidth(),
			area.getHeight(),
			area.getPlane());
	}

	private static Set<WorldPoint> getAttackTiles(WorldArea worldArea)
	{
		Set<WorldPoint> attackTiles = new LinkedHashSet<>();
		int minX = worldArea.getX();
		int maxX = minX + worldArea.getWidth() - 1;
		int minY = worldArea.getY();
		int maxY = minY + worldArea.getHeight() - 1;
		int plane = worldArea.getPlane();

		for (int x = minX; x <= maxX; x++)
		{
			attackTiles.add(new WorldPoint(x, minY - 1, plane));
			attackTiles.add(new WorldPoint(x, maxY + 1, plane));
		}
		for (int y = minY; y <= maxY; y++)
		{
			attackTiles.add(new WorldPoint(minX - 1, y, plane));
			attackTiles.add(new WorldPoint(maxX + 1, y, plane));
		}
		return attackTiles;
	}

	private static boolean isDirectlyAttackable(WorldPoint playerLocation, WorldArea targetArea)
	{
		return playerLocation.toWorldArea().isInMeleeDistance(targetArea);
	}

	private static boolean hasThreeHits(
		WorldPoint playerLocation,
		NpcSnapshot primary,
		List<NpcSnapshot> npcs)
	{
		Direction direction = getDirection(playerLocation, primary.getWorldArea());
		if (direction == null)
		{
			return false;
		}

		Set<WorldPoint> cleaveTiles = getCleaveTiles(playerLocation, direction);
		int secondaryTargets = 0;
		for (NpcSnapshot npc : npcs)
		{
			if (npc.getIndex() != primary.getIndex()
				&& intersectsAnyTile(npc.getWorldArea(), cleaveTiles))
			{
				secondaryTargets++;
				if (secondaryTargets >= REQUIRED_SECONDARY_TARGETS)
				{
					return true;
				}
			}
		}
		return false;
	}

	@Nullable
	private static Direction getDirection(WorldPoint playerLocation, WorldArea targetArea)
	{
		WorldPoint southWest = targetArea.toWorldPoint();
		int deltaX = southWest.getX() - playerLocation.getX();
		int deltaY = southWest.getY() - playerLocation.getY();
		if (deltaX == 0 && deltaY == 0)
		{
			return null;
		}

		if (Math.abs(deltaX) > Math.abs(deltaY))
		{
			return deltaX > 0 ? Direction.EAST : Direction.WEST;
		}

		return deltaY > 0 ? Direction.NORTH : Direction.SOUTH;
	}

	private static boolean intersectsAnyTile(WorldArea worldArea, Set<WorldPoint> tiles)
	{
		int maxX = worldArea.getX() + worldArea.getWidth() - 1;
		int maxY = worldArea.getY() + worldArea.getHeight() - 1;
		for (int x = worldArea.getX(); x <= maxX; x++)
		{
			for (int y = worldArea.getY(); y <= maxY; y++)
			{
				if (tiles.contains(new WorldPoint(x, y, worldArea.getPlane())))
				{
					return true;
				}
			}
		}
		return false;
	}

	private static Set<WorldPoint> getCleaveTiles(WorldPoint playerLocation, Direction direction)
	{
		Set<WorldPoint> tiles = new HashSet<>();
		int x = playerLocation.getX();
		int y = playerLocation.getY();
		int plane = playerLocation.getPlane();

		if (direction == Direction.NORTH || direction == Direction.SOUTH)
		{
			int forwardY = y + direction.dy;
			for (int offset = -1; offset <= 1; offset++)
			{
				tiles.add(new WorldPoint(x + offset, forwardY, plane));
			}
			tiles.add(new WorldPoint(x - 1, y, plane));
			tiles.add(new WorldPoint(x + 1, y, plane));
		}
		else
		{
			int forwardX = x + direction.dx;
			for (int offset = -1; offset <= 1; offset++)
			{
				tiles.add(new WorldPoint(forwardX, y + offset, plane));
			}
			tiles.add(new WorldPoint(x, y - 1, plane));
			tiles.add(new WorldPoint(x, y + 1, plane));
		}
		return tiles;
	}

	private enum Direction
	{
		NORTH(0, 1),
		EAST(1, 0),
		SOUTH(0, -1),
		WEST(-1, 0);

		private final int dx;
		private final int dy;

		Direction(int dx, int dy)
		{
			this.dx = dx;
			this.dy = dy;
		}
	}

	static final class NpcSnapshot
	{
		private final int index;
		private final WorldArea worldArea;
		@Nullable
		private final Integer visibleHealth;
		private final boolean pursuingPlayer;

		NpcSnapshot(int index, WorldArea worldArea)
		{
			this(index, worldArea, null, false);
		}

		NpcSnapshot(int index, WorldArea worldArea, @Nullable Integer visibleHealth)
		{
			this(index, worldArea, visibleHealth, false);
		}

		NpcSnapshot(
			int index,
			WorldArea worldArea,
			@Nullable Integer visibleHealth,
			boolean pursuingPlayer)
		{
			this.index = index;
			this.worldArea = worldArea;
			this.visibleHealth = visibleHealth;
			this.pursuingPlayer = pursuingPlayer;
		}

		int getIndex()
		{
			return index;
		}

		WorldArea getWorldArea()
		{
			return worldArea;
		}

		@Nullable
		Integer getVisibleHealth()
		{
			return visibleHealth;
		}

		boolean isPursuingPlayer()
		{
			return pursuingPlayer;
		}

		NpcSnapshot withWorldArea(WorldArea projectedArea)
		{
			return new NpcSnapshot(index, projectedArea, visibleHealth, pursuingPlayer);
		}
	}

	private static final class MovementState
	{
		private final WorldPoint playerLocation;
		private final List<NpcSnapshot> npcs;

		private MovementState(WorldPoint playerLocation, List<NpcSnapshot> npcs)
		{
			this.playerLocation = playerLocation;
			this.npcs = npcs;
		}

		private WorldPoint getPlayerLocation()
		{
			return playerLocation;
		}

		private List<NpcSnapshot> getNpcs()
		{
			return npcs;
		}
	}

	static final class Recommendation
	{
		private final Set<Integer> targetIndexes;

		private Recommendation(Set<Integer> targetIndexes)
		{
			this.targetIndexes = Collections.unmodifiableSet(new LinkedHashSet<>(targetIndexes));
		}

		private static Recommendation currentTarget(int index)
		{
			return new Recommendation(Collections.singleton(index));
		}

		private static Recommendation targets(Set<Integer> indexes)
		{
			return new Recommendation(indexes);
		}

		Set<Integer> getTargetIndexes()
		{
			return targetIndexes;
		}
	}
}

