public enum HighlightStyle
{
	OUTLINE("Outline"),
	HULL("Filled shape"),
	SOUTH_WEST_TILE("SW tile"),
	OUTLINE_AND_SOUTH_WEST_TILE("Outline and SW tile");

	private final String name;

	HighlightStyle(String name)
	{
		this.name = name;
	}

	boolean drawsOutline()
	{
		return this == OUTLINE || this == OUTLINE_AND_SOUTH_WEST_TILE;
	}

	boolean drawsHull()
	{
		return this == HULL;
	}

	boolean drawsSouthWestTile()
	{
		return this == SOUTH_WEST_TILE || this == OUTLINE_AND_SOUTH_WEST_TILE;
	}

	@Override
	public String toString()
	{
		return name;
	}
}

