import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;
import net.runelite.client.ui.overlay.outline.ModelOutlineRenderer;

final class HallowfellHelperOverlay extends Overlay
{
	private final Client client;
	private final HallowfellHelperConfig config;
	private final HallowfellHelperPlugin plugin;
	private final ModelOutlineRenderer modelOutlineRenderer;

	@Inject
	private HallowfellHelperOverlay(
		Client client,
		HallowfellHelperConfig config,
		HallowfellHelperPlugin plugin,
		ModelOutlineRenderer modelOutlineRenderer)
	{
		this.client = client;
		this.config = config;
		this.plugin = plugin;
		this.modelOutlineRenderer = modelOutlineRenderer;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
		setPriority(PRIORITY_MED);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		Player player = client.getLocalPlayer();
		if (player == null)
		{
			return null;
		}

		HighlightStyle style = config.highlightStyle();
		for (NPC npc : plugin.getHighlightedNpcs())
		{
			if (npc.getWorldView() != player.getWorldView())
			{
				continue;
			}

			if (style.drawsOutline())
			{
				modelOutlineRenderer.drawOutline(
					npc, config.borderWidth(), config.highlightColor(), config.outlineFeather());
			}

			if (style.drawsHull())
			{
				Shape hull = npc.getConvexHull();
				if (hull != null)
				{
					OverlayUtil.renderPolygon(
						graphics,
						hull,
						config.highlightColor(),
						config.fillColor(),
						new BasicStroke(config.borderWidth()));
				}
			}

			if (style.drawsSouthWestTile())
			{
				renderSouthWestTile(graphics, npc);
			}
		}

		WorldPoint fallbackTile = plugin.getFallbackTile();
		if (config.showFallbackTile() && fallbackTile != null)
		{
			renderTile(graphics, player, fallbackTile);
		}
		return null;
	}

	private void renderSouthWestTile(Graphics2D graphics, NPC npc)
	{
		WorldPoint southWest = npc.getWorldArea().toWorldPoint();
		Player player = client.getLocalPlayer();
		if (player == null)
		{
			return;
		}
		renderTile(graphics, player, southWest);
	}

	private void renderTile(Graphics2D graphics, Player player, WorldPoint tile)
	{
		LocalPoint localPoint = LocalPoint.fromWorld(player.getWorldView(), tile);
		if (localPoint == null)
		{
			return;
		}

		Polygon polygon = Perspective.getCanvasTilePoly(client, localPoint);
		if (polygon != null)
		{
			OverlayUtil.renderPolygon(
				graphics,
				polygon,
				config.highlightColor(),
				config.fillColor(),
				new BasicStroke(config.borderWidth()));
		}
	}
}

