import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(
	name = "Hallowfell Helper",
	description = "Highlights NPCs that let Hallowfell hit three targets at once",
	tags = {"hallowfell", "cleave", "combat", "slayer"}
)
public class HallowfellHelperPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private HallowfellHelperConfig config;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private ClientThread clientThread;

	@Inject
	private NPCManager npcManager;

	@Inject
	private HallowfellHelperOverlay overlay;

	private final HallowfellCleaveCalculator calculator = new HallowfellCleaveCalculator();
	private final Set<NPC> trackedNpcs = Collections.newSetFromMap(new IdentityHashMap<>());
	private volatile Set<NPC> highlightedNpcs = Collections.emptySet();
	@Nullable
	private volatile WorldPoint fallbackTile;
	private volatile boolean started;
	private boolean hallowfellEquipped;

	@Override
	protected void startUp()
	{
		started = true;
		overlayManager.add(overlay);
		clientThread.invoke(() ->
		{
			if (started)
			{
				rebuildTrackedNpcs();
				updateEquippedWeapon();
			}
		});
	}

	@Override
	protected void shutDown()
	{
		started = false;
		overlayManager.remove(overlay);
		trackedNpcs.clear();
		highlightedNpcs = Collections.emptySet();
		fallbackTile = null;
		hallowfellEquipped = false;
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		updateRecommendations();
	}

	@Subscribe
	public void onNpcSpawned(NpcSpawned event)
	{
		NPC npc = event.getNpc();
		if (isAttackable(npc))
		{
			trackedNpcs.add(npc);
		}
	}

	@Subscribe
	public void onNpcDespawned(NpcDespawned event)
	{
		trackedNpcs.remove(event.getNpc());
	}

	@Subscribe
	public void onNpcChanged(NpcChanged event)
	{
		NPC npc = event.getNpc();
		trackedNpcs.remove(npc);
		if (isAttackable(npc))
		{
			trackedNpcs.add(npc);
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() == InventoryID.WORN)
		{
			updateEquippedWeapon();
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			rebuildTrackedNpcs();
			updateEquippedWeapon();
		}
		else
		{
			trackedNpcs.clear();
			highlightedNpcs = Collections.emptySet();
			fallbackTile = null;
		}
	}

	Set<NPC> getHighlightedNpcs()
	{
		return highlightedNpcs;
	}

	@Nullable
	WorldPoint getFallbackTile()
	{
		return fallbackTile;
	}

	private void updateRecommendations()
	{
		fallbackTile = null;
		Player player = client.getLocalPlayer();
		if (player == null || !hallowfellEquipped)
		{
			highlightedNpcs = Collections.emptySet();
			return;
		}

		WorldView worldView = player.getWorldView();
		WorldPoint playerLocation = player.getWorldLocation();
		int evaluationRange = config.nearbyRange() + 2;
		List<HallowfellCleaveCalculator.NpcSnapshot> snapshots = new ArrayList<>();
		Map<Integer, NPC> npcsByIndex = new HashMap<>();
		for (NPC npc : trackedNpcs)
		{
			if (npc.getWorldView() != worldView || !isAttackable(npc) || npc.getHealthRatio() == 0)
			{
				continue;
			}
			if (playerLocation.distanceTo(npc.getWorldArea()) > evaluationRange)
			{
				continue;
			}

			snapshots.add(new HallowfellCleaveCalculator.NpcSnapshot(
				npc.getIndex(),
				npc.getWorldArea(),
				estimateVisibleHealth(npc),
				npc.getInteracting() == player));
			npcsByIndex.put(npc.getIndex(), npc);
		}
		snapshots.sort(Comparator.comparingInt(HallowfellCleaveCalculator.NpcSnapshot::getIndex));

		Actor interacting = player.getInteracting();
		Integer currentTargetIndex = interacting instanceof NPC ? ((NPC) interacting).getIndex() : null;
		boolean running = client.getVarpValue(VarPlayerID.OPTION_RUN) == 1 && client.getEnergy() > 0;
		int playerStepsPerTick = running ? 2 : 1;
		int predictionRange = config.nearbyRange();
		HallowfellCleaveCalculator.Recommendation recommendation = calculator.recommend(
			playerLocation,
			snapshots,
			currentTargetIndex,
			predictionRange,
			config.switchBelowHp(),
			worldView,
			playerStepsPerTick);
		if (config.showFallbackTile() && recommendation.getTargetIndexes().isEmpty())
		{
			fallbackTile = calculator.findFallbackTile(
				playerLocation, snapshots, predictionRange, worldView);
		}
		Set<NPC> recommendations = new LinkedHashSet<>();
		for (Integer index : recommendation.getTargetIndexes())
		{
			NPC npc = npcsByIndex.get(index);
			if (npc != null && shouldDisplayTarget(npc))
			{
				recommendations.add(npc);
			}
		}
		highlightedNpcs = Collections.unmodifiableSet(recommendations);
	}

	private boolean shouldDisplayTarget(NPC npc)
	{
		if (!config.onlyLargeNpcs())
		{
			return true;
		}

		WorldArea area = npc.getWorldArea();
		return area.getWidth() > 1 || area.getHeight() > 1;
	}

	private void rebuildTrackedNpcs()
	{
		trackedNpcs.clear();
		Player player = client.getLocalPlayer();
		if (player == null)
		{
			return;
		}

		WorldView worldView = player.getWorldView();
		if (worldView == null)
		{
			return;
		}

		for (NPC npc : worldView.npcs())
		{
			if (isAttackable(npc))
			{
				trackedNpcs.add(npc);
			}
		}
	}

	private void updateEquippedWeapon()
	{
		hallowfellEquipped = false;
		fallbackTile = null;
		ItemContainer equipment = client.getItemContainer(InventoryID.WORN);
		if (equipment == null)
		{
			return;
		}

		Item weapon = equipment.getItem(EquipmentInventorySlot.WEAPON.getSlotIdx());
		hallowfellEquipped = weapon != null && weapon.getId() == ItemID.HALLOWFELL;
	}

	private Integer estimateVisibleHealth(NPC npc)
	{
		int ratio = npc.getHealthRatio();
		int scale = npc.getHealthScale();
		if (ratio < 0 || scale <= 0)
		{
			return null;
		}
		if (ratio == 0)
		{
			return 0;
		}

		Integer maxHealth = npcManager.getHealth(npc.getId());
		if (maxHealth == null)
		{
			return null;
		}

		return Math.min(maxHealth, (maxHealth * ratio + scale - 1) / scale);
	}

	private static boolean isAttackable(NPC npc)
	{
		NPCComposition composition = npc.getTransformedComposition();
		if (composition == null || !composition.isInteractible())
		{
			return false;
		}

		String[] actions = composition.getActions();
		if (actions == null)
		{
			return false;
		}

		for (String action : actions)
		{
			if ("Attack".equals(action))
			{
				return true;
			}
		}
		return false;
	}

	@Provides
	HallowfellHelperConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(HallowfellHelperConfig.class);
	}
}

