{
	@ConfigItem(
		keyName = "highlightStyle",
		name = "Highlight style",
		description = "Choose how suggested targets are marked.",
		position = 0
	)
	default HighlightStyle highlightStyle()
	{
		return HighlightStyle.OUTLINE;
	}

	@Alpha
	@ConfigItem(
		keyName = "highlightColor",
		name = "Highlight color",
		description = "Choose the color used for suggested targets.",
		position = 1
	)
	default Color highlightColor()
	{
		return Color.GREEN;
	}

	@Alpha
	@ConfigItem(
		keyName = "fillColor",
		name = "Fill color",
		description = "Choose the fill color for filled shapes and tiles.",
		position = 2
	)
	default Color fillColor()
	{
		return new Color(0, 255, 0, 40);
	}

	@Range(min = 1, max = 4)
	@ConfigItem(
		keyName = "borderWidth",
		name = "Border width",
		description = "Set the width of outlines and tile borders.",
		position = 3
	)
	default int borderWidth()
	{
		return 2;
	}

	@Range(min = 0, max = 4)
	@ConfigItem(
		keyName = "outlineFeather",
		name = "Outline softness",
		description = "Set how soft model outlines appear.",
		position = 4
	)
	default int outlineFeather()
	{
		return 0;
	}

	@Range(min = 2, max = 5)
	@ConfigItem(
		keyName = "nearbyRange",
		name = "Search distance",
		description = "How many tiles away to look for a target when none<br>"
			+ "are available beside you.",
		position = 5
	)
	default int nearbyRange()
	{
		return 3;
	}

	@ConfigItem(
		keyName = "showFallbackTile",
		name = "Show where to stand",
		description = "Highlight a nearby tile that creates a three-target hit.<br>"
			+ "Only shown when there is no suggested NPC.",
		position = 6
	)
	default boolean showFallbackTile()
	{
		return true;
	}

	@Range(min = 0, max = 1000)
	@ConfigItem(
		keyName = "switchBelowHp",
		name = "Switch target below HP",
		description = "Suggest a healthier NPC that can still give you three hits<br>"
			+ "when your current target reaches this much visible HP.<br>"
			+ "Set to 0 to turn this off.",
		position = 7
	)
	default int switchBelowHp()
	{
		return 25;
	}

	@ConfigItem(
		keyName = "onlyLargeNpcs",
		name = "Large NPCs only",
		description = "Only highlight NPCs that cover more than one tile.",
		position = 8
	)
	default boolean onlyLargeNpcs()
	{
		return false;
	}
}
